<?php
declare(strict_types=1);
require_once __DIR__ . '/config/customer_membership.php';

$error=null;$success=null;$user=null;$csrf='';$memberships=[];$customers=[];$crmCustomers=[];$coaches=[];$labels=[];$promos=[];$products=[];$tiers=[];$editMembership=null;$editLabel=null;$editPromo=null;
function cmm_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function cmm_text(string $k,string $d=''):string{return trim((string)($_POST[$k]??$d));}
function cmm_int(string $k,int $d=0):int{return (int)($_POST[$k]??$d);}
try{
    $pdo=role_portal_db();cm_ensure($pdo);security_step17_session_start();$user=security_step17_session_user($pdo,true);
    if(!$user){header('Location: ../login.php');exit;}
    if((int)($user['must_change_password']??0)===1){header('Location: ../change_password.php?required=1');exit;}
    $role=(string)($user['role_code']??'');$isAdmin=$role==='admin';$isCoach=$role==='coach';
    if(!$isAdmin&&!$isCoach){header('Location: access_denied.php?permission=customers.manage');exit;}
    if(!security_step17_has_permission($pdo,'customers.manage',$user)&&!$isAdmin){header('Location: access_denied.php?permission=customers.manage');exit;}
    $ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];$csrf=security_step17_csrf();

    if($_SERVER['REQUEST_METHOD']==='POST'){
        security_step17_verify_csrf((string)($_POST['csrf']??''));$action=cmm_text('action');
        if($action==='save_membership'){
            $profileId=max(0,cmm_int('profile_id'));$customerUserId=max(0,cmm_int('user_id'));$crmId=max(0,cmm_int('crm_customer_id'));$labelId=max(0,cmm_int('discount_label_id'));$status=cmm_text('membership_status','pending');$joined=cmm_text('joined_at');$notes=cmm_text('notes');$memberCode=strtoupper(cmm_text('member_code'));
            if(!in_array($status,['pending','active','suspended'],true))$status='pending';
            $q=$pdo->prepare("SELECT u.id,u.full_name,u.email FROM system_users u JOIN organization_user_access a ON a.user_id=u.id AND a.organization_id=? WHERE u.id=? AND a.role_code='customer' AND u.is_active=1 AND a.is_active=1 LIMIT 1");$q->execute([$orgId,$customerUserId]);$customerAccount=$q->fetch();if(!$customerAccount)throw new RuntimeException('Choose an active Customer login account.');
            if($labelId>0){$q=$pdo->prepare("SELECT id FROM customer_discount_labels WHERE organization_id=? AND id=? AND status='active'");$q->execute([$orgId,$labelId]);if(!(int)$q->fetchColumn())throw new RuntimeException('Choose a valid active discount label.');}
            if($status==='active'&&$labelId<=0)throw new RuntimeException('An active Club Member must have a discount label.');
            $coachId=$isCoach?(int)$user['id']:max(0,cmm_int('coach_user_id'));
            if($coachId>0){$q=$pdo->prepare("SELECT u.id FROM system_users u JOIN organization_user_access a ON a.user_id=u.id AND a.organization_id=? WHERE u.id=? AND a.role_code='coach' AND u.is_active=1 AND a.is_active=1");$q->execute([$orgId,$coachId]);if(!(int)$q->fetchColumn())throw new RuntimeException('Choose a valid active Coach.');}
            $old=null;if($profileId>0){$q=$pdo->prepare("SELECT * FROM customer_membership_profiles WHERE organization_id=? AND id=? LIMIT 1");$q->execute([$orgId,$profileId]);$old=$q->fetch();if(!$old)throw new RuntimeException('Membership record not found.');if($isCoach&&(int)($old['coach_user_id']??0)!==(int)$user['id'])throw new RuntimeException('A Coach may manage only customers assigned to that Coach.');}
            if($memberCode==='')$memberCode=cm_generate_member_code($pdo,$orgId);
            if(!preg_match('/^[A-Z0-9-]{6,60}$/',$memberCode))throw new RuntimeException('Club Member ID may contain only letters, numbers and hyphens.');
            $q=$pdo->prepare("SELECT id FROM customer_membership_profiles WHERE organization_id=? AND member_code=? AND id<>? LIMIT 1");$q->execute([$orgId,$memberCode,$profileId]);if($q->fetchColumn())throw new RuntimeException('This Club Member ID is already in use.');
            if($crmId>0&&business_table_exists($pdo,'crm_customers')){$q=$pdo->prepare("SELECT id FROM crm_customers WHERE organization_id=? AND id=? LIMIT 1");$q->execute([$orgId,$crmId]);if(!$q->fetchColumn())throw new RuntimeException('Linked CRM Customer was not found.');}
            $joined=$joined!==''?$joined:null;
            if($profileId>0){$s=$pdo->prepare("UPDATE customer_membership_profiles SET user_id=?,crm_customer_id=?,member_code=?,coach_user_id=?,discount_label_id=?,membership_status=?,joined_at=?,verified_at=CASE WHEN ?='active' THEN COALESCE(verified_at,NOW()) ELSE verified_at END,assigned_by=?,notes=? WHERE organization_id=? AND id=?");$s->execute([$customerUserId,$crmId?:null,$memberCode,$coachId?:null,$labelId?:null,$status,$joined,$status,(int)$user['id'],$notes?:null,$orgId,$profileId]);}
            else{$s=$pdo->prepare("INSERT INTO customer_membership_profiles(organization_id,user_id,crm_customer_id,member_code,coach_user_id,discount_label_id,membership_status,joined_at,verified_at,assigned_by,notes) VALUES(?,?,?,?,?,?,?,?,CASE WHEN ?='active' THEN NOW() ELSE NULL END,?,?)");$s->execute([$orgId,$customerUserId,$crmId?:null,$memberCode,$coachId?:null,$labelId?:null,$status,$joined,$status,(int)$user['id'],$notes?:null]);$profileId=(int)$pdo->lastInsertId();}
            security_step17_audit($pdo,(int)$user['id'],'customer_membership_saved','customer_membership',$profileId,['customer_user_id'=>$customerUserId,'member_code'=>$memberCode,'coach_user_id'=>$coachId?:null,'label_id'=>$labelId?:null,'status'=>$status]);$success='Club membership saved. Member ID: '.$memberCode;$_GET['edit_membership']=$profileId;
        }
        elseif($action==='save_label'){
            if(!$isAdmin)throw new RuntimeException('Only the Administrator can edit discount labels.');
            $id=max(0,cmm_int('label_id'));$code=strtoupper(preg_replace('/[^A-Z0-9]+/','_',cmm_text('label_code'))??'');$name=cmm_text('label_name');$badge=cmm_text('badge_text');$tier=cmm_text('pricing_tier_code');$headline=cmm_text('headline');$desc=cmm_text('description');$style=cmm_text('card_style','green');$sort=cmm_int('sort_order',10);$status=cmm_text('status','active');
            if($code===''||$name==='')throw new RuntimeException('Label code and name are required.');if(!in_array($status,['active','inactive'],true))$status='active';if(!in_array($style,['green','bronze','silver','gold','blue','purple','coral'],true))$style='green';
            if($tier!==''){$q=$pdo->prepare("SELECT COUNT(*) FROM product_discount_tiers t JOIN product_markets m ON m.id=t.market_id WHERE t.organization_id=? AND t.tier_code=? AND t.status='active' AND m.market_code='IN'");$q->execute([$orgId,$tier]);if((int)$q->fetchColumn()!==1)throw new RuntimeException('Choose a valid active exact-price tier.');}
            if($id>0){$s=$pdo->prepare("UPDATE customer_discount_labels SET label_code=?,label_name=?,badge_text=?,pricing_tier_code=?,headline=?,description=?,card_style=?,sort_order=?,status=? WHERE organization_id=? AND id=?");$s->execute([$code,$name,$badge?:null,$tier?:null,$headline?:null,$desc?:null,$style,$sort,$status,$orgId,$id]);}
            else{$s=$pdo->prepare("INSERT INTO customer_discount_labels(organization_id,label_code,label_name,badge_text,pricing_tier_code,headline,description,card_style,sort_order,status) VALUES(?,?,?,?,?,?,?,?,?,?)");$s->execute([$orgId,$code,$name,$badge?:null,$tier?:null,$headline?:null,$desc?:null,$style,$sort,$status]);$id=(int)$pdo->lastInsertId();}
            security_step17_audit($pdo,(int)$user['id'],'customer_discount_label_saved','customer_discount_label',$id,['label_code'=>$code,'pricing_tier_code'=>$tier]);$success='Discount label saved.';$_GET['edit_label']=$id;
        }
        elseif($action==='save_promo'){
            if(!$isAdmin)throw new RuntimeException('Only the Administrator can edit customer offers.');
            $id=max(0,cmm_int('promo_id'));$code=strtoupper(preg_replace('/[^A-Z0-9]+/','-',cmm_text('promotion_code'))??'');$type=cmm_text('promotion_type','join_club');$scope=cmm_text('customer_scope','regular');$productId=max(0,cmm_int('product_id'));$title=cmm_text('title');$badge=cmm_text('badge_text');$subtitle=cmm_text('subtitle');$desc=cmm_text('description');$minQty=max(1,cmm_int('min_qty',1));$minVp=max(0,(float)cmm_text('min_vp','0'));$discountType=cmm_text('discount_type','informational');$discountValue=max(0,(float)cmm_text('discount_value','0'));$style=cmm_text('display_style','green');$starts=cmm_text('starts_at');$ends=cmm_text('ends_at');$sort=cmm_int('sort_order',10);$status=cmm_text('status','active');
            if($code===''||$title==='')throw new RuntimeException('Offer code and title are required.');if(!in_array($type,['join_club','product','bulk'],true))throw new RuntimeException('Choose a valid offer type.');if(!in_array($scope,['all','regular','member'],true))$scope='regular';if(!in_array($discountType,['informational','percent','fixed'],true))$discountType='informational';if($discountType==='percent'&&$discountValue>100)throw new RuntimeException('Percent discount cannot exceed 100.');if(!in_array($status,['active','inactive'],true))$status='active';if(!in_array($style,['green','bronze','silver','gold','blue','purple','coral'],true))$style='green';
            if($productId>0){$q=$pdo->prepare("SELECT COUNT(*) FROM products WHERE organization_id=? AND id=?");$q->execute([$orgId,$productId]);if((int)$q->fetchColumn()!==1)throw new RuntimeException('Selected product was not found.');}
            $starts=$starts!==''?str_replace('T',' ',$starts).':00':null;$ends=$ends!==''?str_replace('T',' ',$ends).':00':null;
            $args=[$code,$type,$scope,$productId?:null,$title,$badge?:null,$subtitle?:null,$desc?:null,$minQty,$minVp,$discountType,$discountValue,$style,$starts,$ends,$status,$sort];
            if($id>0){$s=$pdo->prepare("UPDATE customer_promotions SET promotion_code=?,promotion_type=?,customer_scope=?,product_id=?,title=?,badge_text=?,subtitle=?,description=?,min_qty=?,min_vp=?,discount_type=?,discount_value=?,display_style=?,starts_at=?,ends_at=?,status=?,sort_order=? WHERE organization_id=? AND id=?");$s->execute([...$args,$orgId,$id]);}
            else{$s=$pdo->prepare("INSERT INTO customer_promotions(organization_id,promotion_code,promotion_type,customer_scope,product_id,title,badge_text,subtitle,description,min_qty,min_vp,discount_type,discount_value,display_style,starts_at,ends_at,status,sort_order) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)");$s->execute([$orgId,...$args]);$id=(int)$pdo->lastInsertId();}
            security_step17_audit($pdo,(int)$user['id'],'customer_promotion_saved','customer_promotion',$id,['promotion_code'=>$code,'type'=>$type,'scope'=>$scope,'discount_type'=>$discountType,'discount_value'=>$discountValue]);$success='Customer offer saved.';$_GET['edit_promo']=$id;
        }
    }

    $q=$pdo->prepare("SELECT u.id,u.full_name,u.email,u.mobile FROM system_users u JOIN organization_user_access a ON a.user_id=u.id AND a.organization_id=? WHERE a.role_code='customer' AND u.is_active=1 AND a.is_active=1 ORDER BY u.full_name");$q->execute([$orgId]);$customers=$q->fetchAll();
    if(business_table_exists($pdo,'crm_customers')){$q=$pdo->prepare("SELECT id,customer_code,customer_name,mobile FROM crm_customers WHERE organization_id=? AND status='active' ORDER BY customer_name");$q->execute([$orgId]);$crmCustomers=$q->fetchAll();}
    $q=$pdo->prepare("SELECT u.id,u.full_name,u.email FROM system_users u JOIN organization_user_access a ON a.user_id=u.id AND a.organization_id=? WHERE a.role_code='coach' AND u.is_active=1 AND a.is_active=1 ORDER BY u.full_name");$q->execute([$orgId]);$coaches=$q->fetchAll();
    $q=$pdo->prepare("SELECT * FROM customer_discount_labels WHERE organization_id=? ORDER BY sort_order,label_name");$q->execute([$orgId]);$labels=$q->fetchAll();
    $q=$pdo->prepare("SELECT p.*,pr.product_name,pr.sku FROM customer_promotions p LEFT JOIN products pr ON pr.id=p.product_id WHERE p.organization_id=? ORDER BY p.sort_order,p.id");$q->execute([$orgId]);$promos=$q->fetchAll();
    $q=$pdo->prepare("SELECT id,sku,product_name FROM products WHERE organization_id=? AND status='active' ORDER BY product_name");$q->execute([$orgId]);$products=$q->fetchAll();
    $q=$pdo->prepare("SELECT DISTINCT t.tier_code,t.tier_name FROM product_discount_tiers t JOIN product_markets m ON m.id=t.market_id WHERE t.organization_id=? AND t.status='active' AND m.market_code='IN' ORDER BY t.sort_order");$q->execute([$orgId]);$tiers=$q->fetchAll();
    $sql="SELECT m.*,u.full_name customer_name,u.email,l.label_name,l.badge_text,l.pricing_tier_code,c.full_name coach_name,crm.customer_name crm_name FROM customer_membership_profiles m JOIN system_users u ON u.id=m.user_id LEFT JOIN customer_discount_labels l ON l.id=m.discount_label_id LEFT JOIN system_users c ON c.id=m.coach_user_id LEFT JOIN crm_customers crm ON crm.id=m.crm_customer_id WHERE m.organization_id=?";$args=[$orgId];if($isCoach){$sql.=" AND m.coach_user_id=?";$args[]=(int)$user['id'];}$sql.=" ORDER BY FIELD(m.membership_status,'pending','active','suspended'),u.full_name";$q=$pdo->prepare($sql);$q->execute($args);$memberships=$q->fetchAll();
    $editMembershipId=max(0,(int)($_GET['edit_membership']??0));if($editMembershipId){foreach($memberships as $r)if((int)$r['id']===$editMembershipId)$editMembership=$r;}
    $editLabelId=max(0,(int)($_GET['edit_label']??0));if($isAdmin&&$editLabelId){foreach($labels as $r)if((int)$r['id']===$editLabelId)$editLabel=$r;}
    $editPromoId=max(0,(int)($_GET['edit_promo']??0));if($isAdmin&&$editPromoId){foreach($promos as $r)if((int)$r['id']===$editPromoId)$editPromo=$r;}
}catch(Throwable $e){$error=$e->getMessage();}
$isAdmin=(string)($user['role_code']??'')==='admin';$isCoach=(string)($user['role_code']??'')==='coach';
?><!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Club Members & Offers - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><link rel="stylesheet" href="assets/workspace_refresh.css"><style>
.cm-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(360px,.8fr);gap:14px;margin-top:14px}.cm-card{padding:18px;border:1px solid #dce8e1;border-radius:18px;background:#fff}.cm-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.cm-form label{display:grid;gap:5px;color:#52685d;font-size:.7rem;font-weight:800}.cm-form .wide{grid-column:1/-1}.cm-form input,.cm-form select,.cm-form textarea{width:100%;padding:10px 11px;border:1px solid #d8e4dd;border-radius:10px;background:#fbfdfc;color:#173c2c}.cm-form textarea{min-height:80px;resize:vertical}.cm-form button{grid-column:1/-1;padding:11px 14px;border:0;border-radius:11px;background:#176f45;color:white;font-weight:850}.cm-table{width:100%;border-collapse:collapse;font-size:.7rem}.cm-table th,.cm-table td{padding:9px 8px;border-bottom:1px solid #e4ece7;text-align:left;vertical-align:top}.cm-table small{display:block;color:#73847b;margin-top:3px}.cm-badge{display:inline-flex;padding:5px 8px;border-radius:999px;background:#eef8f2;color:#176f45;font-size:.58rem;font-weight:900;letter-spacing:.04em}.cm-note{padding:12px 14px;border:1px solid #e7ddbd;border-radius:13px;background:#fffaf0;color:#725d2d;font-size:.72rem;line-height:1.6}.cm-section-title{display:flex;justify-content:space-between;gap:10px;align-items:end;margin-bottom:12px}.cm-section-title h2{margin:0}.cm-offer-list{display:grid;gap:8px}.cm-offer{padding:12px;border:1px solid #dce8e1;border-radius:13px;background:#fbfdfc}.cm-offer b{color:#173c2c}.cm-offer p{margin:4px 0 0;color:#6d7e75;font-size:.68rem}.cm-split{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:14px}@media(max-width:1000px){.cm-grid,.cm-split{grid-template-columns:1fr}}@media(max-width:620px){.cm-form{grid-template-columns:1fr}.cm-form .wide{grid-column:auto}.cm-table{font-size:.64rem}}
</style></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="index.php"><img src="../img/logo.png" alt="Healthcare Wellness Club"><span><strong>Healthcare Wellness Club</strong><small>Club Members • Discount Labels • Customer Offers</small></span></a><div class="os-top-actions"><a class="os-btn" href="../feature_hub.php">All Features</a><a class="os-btn" href="customer_center.php">Customers</a><a class="os-btn primary" href="index.php">Dashboard</a></div></div></header><main class="os-main" style="max-width:1500px;margin:auto"><section class="os-hero pp-hero"><div class="os-kicker">CUSTOMER MEMBERSHIP & PRICING</div><h1>Separate regular customers from verified Club Members — then assign pricing and offers deliberately.</h1><p>Regular customers keep normal MRP access. A Club Member receives a unique Club Member ID and an Administrator/assigned Coach controls the member status and discount label. Exact member tiers are applied server-side; customer offers can be presented and edited without changing product source prices.</p><div class="os-status-row"><span class="os-chip good"><?= $isAdmin?'ADMIN CONTROL':'COACH CONTROL' ?></span><span class="os-chip"><?=count($memberships)?> memberships</span><span class="os-chip"><?=count($labels)?> labels</span><span class="os-chip"><?=count($promos)?> offers</span><span class="os-chip">Home delivery: ₹118 below 100 VP • ₹0 at 100+ VP</span></div></section><?php if($error):?><div class="pp-alert bad" style="margin-top:14px"><?=cmm_h($error)?></div><?php endif;?><?php if($success):?><div class="pp-alert good" style="margin-top:14px"><?=cmm_h($success)?></div><?php endif;?>
<?php if(!$error):?><section class="cm-grid"><article class="cm-card"><div class="cm-section-title"><div><h2><?= $editMembership?'Edit Club Member':'Assign Club Membership' ?></h2><p>Only verified Customer login accounts can receive a Club Member ID.</p></div><?php if($editMembership):?><a href="customer_membership_manager.php">New</a><?php endif;?></div><form method="post" class="cm-form"><input type="hidden" name="csrf" value="<?=cmm_h($csrf)?>"><input type="hidden" name="action" value="save_membership"><input type="hidden" name="profile_id" value="<?=(int)($editMembership['id']??0)?>"><label>Customer Login Account<select name="user_id" required><option value="">Choose customer</option><?php foreach($customers as $c):?><option value="<?=(int)$c['id']?>" <?=(int)($editMembership['user_id']??0)===(int)$c['id']?'selected':''?>><?=cmm_h($c['full_name'].' • '.$c['email'])?></option><?php endforeach;?></select></label><label>Club Member ID<input name="member_code" value="<?=cmm_h($editMembership['member_code']??'')?>" placeholder="Leave blank to auto-generate"></label><label>Discount Label<select name="discount_label_id"><option value="">Not assigned</option><?php foreach($labels as $l):if($l['status']!=='active')continue;?><option value="<?=(int)$l['id']?>" <?=(int)($editMembership['discount_label_id']??0)===(int)$l['id']?'selected':''?>><?=cmm_h($l['label_name'].' • '.($l['pricing_tier_code']?:'No price tier'))?></option><?php endforeach;?></select></label><?php if($isAdmin):?><label>Assigned Coach<select name="coach_user_id"><option value="">Administrator managed</option><?php foreach($coaches as $c):?><option value="<?=(int)$c['id']?>" <?=(int)($editMembership['coach_user_id']??0)===(int)$c['id']?'selected':''?>><?=cmm_h($c['full_name'])?></option><?php endforeach;?></select></label><?php else:?><label>Assigned Coach<input value="<?=cmm_h($user['full_name'])?>" disabled></label><?php endif;?><label>CRM Customer Link (optional)<select name="crm_customer_id"><option value="">No CRM link</option><?php foreach($crmCustomers as $c):?><option value="<?=(int)$c['id']?>" <?=(int)($editMembership['crm_customer_id']??0)===(int)$c['id']?'selected':''?>><?=cmm_h($c['customer_name'].' • '.$c['customer_code'])?></option><?php endforeach;?></select></label><label>Membership Status<select name="membership_status"><option value="pending" <?=($editMembership['membership_status']??'pending')==='pending'?'selected':''?>>Pending</option><option value="active" <?=($editMembership['membership_status']??'')==='active'?'selected':''?>>Active / Verified</option><option value="suspended" <?=($editMembership['membership_status']??'')==='suspended'?'selected':''?>>Suspended</option></select></label><label>Joined Date<input type="date" name="joined_at" value="<?=cmm_h($editMembership['joined_at']??date('Y-m-d'))?>"></label><label class="wide">Internal Membership Note<textarea name="notes"><?=cmm_h($editMembership['notes']??'')?></textarea></label><button><?= $editMembership?'Update Membership':'Create / Assign Membership' ?> →</button></form><div class="cm-note" style="margin-top:12px">Club Member ID is an account identifier, not a password. Password, MFA and trusted-device security remain separate.</div></article><article class="cm-card"><div class="cm-section-title"><div><h2>Club Member Register</h2><p><?= $isCoach?'Only customers assigned to you are shown.':'Administrator sees all membership records.' ?></p></div></div><div style="overflow:auto"><table class="cm-table"><thead><tr><th>Member</th><th>ID</th><th>Label</th><th>Coach</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($memberships as $m):?><tr><td><b><?=cmm_h($m['customer_name'])?></b><small><?=cmm_h($m['email'])?></small></td><td><b><?=cmm_h($m['member_code'])?></b></td><td><?=cmm_h($m['label_name']?:'—')?><small><?=cmm_h($m['pricing_tier_code']?:'')?></small></td><td><?=cmm_h($m['coach_name']?:'Administrator')?></td><td><span class="cm-badge"><?=cmm_h(strtoupper($m['membership_status']))?></span></td><td><a href="?edit_membership=<?=(int)$m['id']?>">Edit</a></td></tr><?php endforeach;?><?php if(!$memberships):?><tr><td colspan="6">No Club Member profiles yet.</td></tr><?php endif;?></tbody></table></div></article></section>
<?php if($isAdmin):?><section class="cm-split"><article class="cm-card"><div class="cm-section-title"><div><h2>Discount Labels</h2><p>Map a customer-facing label to an exact active product price tier.</p></div><?php if($editLabel):?><a href="customer_membership_manager.php">New</a><?php endif;?></div><form method="post" class="cm-form"><input type="hidden" name="csrf" value="<?=cmm_h($csrf)?>"><input type="hidden" name="action" value="save_label"><input type="hidden" name="label_id" value="<?=(int)($editLabel['id']??0)?>"><label>Label Code<input name="label_code" value="<?=cmm_h($editLabel['label_code']??'')?>" placeholder="GOLD"></label><label>Label Name<input name="label_name" value="<?=cmm_h($editLabel['label_name']??'')?>" placeholder="Club Gold"></label><label>Badge Text<input name="badge_text" value="<?=cmm_h($editLabel['badge_text']??'')?>" placeholder="GOLD MEMBER"></label><label>Exact Price Tier<select name="pricing_tier_code"><option value="">Informational only</option><?php foreach($tiers as $t):?><option value="<?=cmm_h($t['tier_code'])?>" <?=($editLabel['pricing_tier_code']??'')===$t['tier_code']?'selected':''?>><?=cmm_h($t['tier_name'].' • '.$t['tier_code'])?></option><?php endforeach;?></select></label><label class="wide">Headline<input name="headline" value="<?=cmm_h($editLabel['headline']??'')?>"></label><label class="wide">Description<textarea name="description"><?=cmm_h($editLabel['description']??'')?></textarea></label><label>Card Style<select name="card_style"><?php foreach(['green','bronze','silver','gold','blue','purple','coral'] as $s):?><option value="<?=$s?>" <?=($editLabel['card_style']??'green')===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select></label><label>Sort Order<input type="number" name="sort_order" value="<?=cmm_h($editLabel['sort_order']??10)?>"></label><label>Status<select name="status"><option value="active" <?=($editLabel['status']??'active')==='active'?'selected':''?>>Active</option><option value="inactive" <?=($editLabel['status']??'')==='inactive'?'selected':''?>>Inactive</option></select></label><button>Save Discount Label →</button></form><div class="cm-offer-list" style="margin-top:12px"><?php foreach($labels as $l):?><div class="cm-offer"><span class="cm-badge"><?=cmm_h($l['badge_text']?:$l['label_code'])?></span> <b><?=cmm_h($l['label_name'])?></b><p>Tier: <?=cmm_h($l['pricing_tier_code']?:'Informational')?> • <?=cmm_h(strtoupper($l['status']))?> • <a href="?edit_label=<?=(int)$l['id']?>">Edit</a></p></div><?php endforeach;?></div></article><article class="cm-card"><div class="cm-section-title"><div><h2>Customer Offers & Bulk Discounts</h2><p>Create attractive regular/member offers. Numeric product/bulk rules are server-applied when eligible.</p></div><?php if($editPromo):?><a href="customer_membership_manager.php">New</a><?php endif;?></div><form method="post" class="cm-form"><input type="hidden" name="csrf" value="<?=cmm_h($csrf)?>"><input type="hidden" name="action" value="save_promo"><input type="hidden" name="promo_id" value="<?=(int)($editPromo['id']??0)?>"><label>Offer Code<input name="promotion_code" value="<?=cmm_h($editPromo['promotion_code']??'')?>" placeholder="BULK-5"></label><label>Offer Type<select name="promotion_type"><?php foreach(['join_club'=>'Join Club','product'=>'Product Discount','bulk'=>'Bulk Product Discount'] as $k=>$v):?><option value="<?=$k?>" <?=($editPromo['promotion_type']??'join_club')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Customer Scope<select name="customer_scope"><?php foreach(['regular'=>'Regular Customers','member'=>'Club Members','all'=>'All Customers'] as $k=>$v):?><option value="<?=$k?>" <?=($editPromo['customer_scope']??'regular')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Product (optional)<select name="product_id"><option value="">All eligible products</option><?php foreach($products as $p):?><option value="<?=(int)$p['id']?>" <?=(int)($editPromo['product_id']??0)===(int)$p['id']?'selected':''?>><?=cmm_h($p['product_name'].' • '.$p['sku'])?></option><?php endforeach;?></select></label><label class="wide">Offer Title<input name="title" value="<?=cmm_h($editPromo['title']??'')?>"></label><label>Badge Text<input name="badge_text" value="<?=cmm_h($editPromo['badge_text']??'')?>"></label><label>Subtitle<input name="subtitle" value="<?=cmm_h($editPromo['subtitle']??'')?>"></label><label class="wide">Description<textarea name="description"><?=cmm_h($editPromo['description']??'')?></textarea></label><label>Minimum Quantity<input type="number" min="1" name="min_qty" value="<?=cmm_h($editPromo['min_qty']??1)?>"></label><label>Minimum Order VP<input type="number" min="0" step="0.001" name="min_vp" value="<?=cmm_h($editPromo['min_vp']??0)?>"></label><label>Discount Type<select name="discount_type"><option value="informational" <?=($editPromo['discount_type']??'informational')==='informational'?'selected':''?>>Informational only</option><option value="percent" <?=($editPromo['discount_type']??'')==='percent'?'selected':''?>>Percent off</option><option value="fixed" <?=($editPromo['discount_type']??'')==='fixed'?'selected':''?>>₹ Fixed off per unit</option></select></label><label>Discount Value<input type="number" min="0" step="0.01" name="discount_value" value="<?=cmm_h($editPromo['discount_value']??0)?>"></label><label>Display Style<select name="display_style"><?php foreach(['green','bronze','silver','gold','blue','purple','coral'] as $s):?><option value="<?=$s?>" <?=($editPromo['display_style']??'green')===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select></label><label>Sort Order<input type="number" name="sort_order" value="<?=cmm_h($editPromo['sort_order']??10)?>"></label><label>Starts At<input type="datetime-local" name="starts_at" value="<?=!empty($editPromo['starts_at'])?cmm_h(date('Y-m-d\TH:i',strtotime($editPromo['starts_at']))):''?>"></label><label>Ends At<input type="datetime-local" name="ends_at" value="<?=!empty($editPromo['ends_at'])?cmm_h(date('Y-m-d\TH:i',strtotime($editPromo['ends_at']))):''?>"></label><label>Status<select name="status"><option value="active" <?=($editPromo['status']??'active')==='active'?'selected':''?>>Active</option><option value="inactive" <?=($editPromo['status']??'')==='inactive'?'selected':''?>>Inactive</option></select></label><button>Save Customer Offer →</button></form><div class="cm-offer-list" style="margin-top:12px"><?php foreach($promos as $p):?><div class="cm-offer"><span class="cm-badge"><?=cmm_h($p['badge_text']?:strtoupper($p['promotion_type']))?></span> <b><?=cmm_h($p['title'])?></b><p><?=cmm_h(strtoupper($p['customer_scope']))?> • <?=cmm_h($p['product_name']?:'All products')?> • <?=cmm_h($p['discount_type'])?> <?=($p['discount_type']!=='informational'?cmm_h($p['discount_value']):'')?> • <a href="?edit_promo=<?=(int)$p['id']?>">Edit</a></p></div><?php endforeach;?></div></article></section><?php endif;?>
<div class="os-footer-note"><strong>Pricing boundary:</strong> Club labels point to exact stored tier prices. Custom product/bulk offers are separate club promotions and are applied only when an Administrator explicitly configures a numeric rule.</div><?php endif;?></main><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
